DROP DATABASE IF EXISTS mercadao_pet;
CREATE DATABASE mercadao_pet
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_0900_ai_ci;
USE mercadao_pet;

CREATE TABLE cliente (
    id_cliente 	INT AUTO_INCREMENT PRIMARY KEY,
    nome 		VARCHAR(100) NOT NULL,
    cpf 		CHAR(11) NOT NULL UNIQUE,
    endereco 	VARCHAR(200) NOT NULL,
    telefone 	VARCHAR(11) NOT NULL
);

CREATE TABLE pet (
    id_pet 		INT AUTO_INCREMENT PRIMARY KEY,
    nome 		VARCHAR(100) NOT NULL,
    especie		VARCHAR(50) NOT NULL,
    raca 		VARCHAR(50) NOT NULL,
    peso 		DECIMAL(5,2) NOT NULL,
    pelagem 	VARCHAR(50) NOT NULL,
    data_nascimento DATE NOT NULL,
    sexo 		CHAR(1) NOT NULL,
    id_cliente 	INT NOT NULL
);

CREATE TABLE historico (
    id_historico 	INT AUTO_INCREMENT PRIMARY KEY,
    data 			DATE NOT NULL,
    tipo_atendimento VARCHAR(50) NOT NULL,
    descricao 		VARCHAR(200) NOT NULL,
    observacoes 	VARCHAR(200),
    id_pet 			INT NOT NULL
);

CREATE TABLE servico (
    id_servico 		INT AUTO_INCREMENT PRIMARY KEY,
    nome 			VARCHAR(100) NOT NULL,
    descricao 		VARCHAR(200) NOT NULL,
    tipo			VARCHAR(50) NOT NULL,
    preco 			DECIMAL(10,2) NOT NULL
);

CREATE TABLE funcionario (
    id_funcionario 		INT AUTO_INCREMENT PRIMARY KEY,
    nome 				VARCHAR(100) NOT NULL,
    cpf 				CHAR(11) NOT NULL UNIQUE,
    cargo 				VARCHAR(50) NOT NULL,
    telefone 			VARCHAR(11) NOT NULL
);

CREATE TABLE agendamento (
    id_agendamento 		INT AUTO_INCREMENT PRIMARY KEY,
    data 				DATE NOT NULL,
    hora 				TIME NOT NULL,
    endereco 			VARCHAR(200),
    observacoes 		VARCHAR(200),
    status 				VARCHAR(20) NOT NULL DEFAULT 'AGENDADO',
    id_pet 				INT NOT NULL,  
    id_funcionario 		INT NOT NULL
);

CREATE TABLE agendamento_servico (
    id_agendamento 	INT NOT NULL,
    id_servico 		INT NOT NULL,
    PRIMARY KEY (id_agendamento, id_servico)
);

CREATE TABLE funcionario_servico (
    id_funcionario 	INT NOT NULL,
    id_servico 		INT NOT NULL,
    PRIMARY KEY (id_funcionario, id_servico)
);

CREATE TABLE transporte (
    id_transporte 		INT AUTO_INCREMENT PRIMARY KEY,
    endereco_origem 	VARCHAR(200) NOT NULL,
    endereco_destino 	VARCHAR(200) NOT NULL,
    tipo_transporte 	VARCHAR(50)  NOT NULL,
    data DATE         	NOT NULL,
    hora             	TIME         NOT NULL,
    status           	VARCHAR(20)  NOT NULL DEFAULT 'PENDENTE',
    id_agendamento   	INT          NOT NULL UNIQUE
);

CREATE TABLE entrega (
    id_entrega     INT AUTO_INCREMENT PRIMARY KEY,
    endereco       VARCHAR(200) NOT NULL,
    status         VARCHAR(20)  NOT NULL DEFAULT 'PENDENTE',
    data_entrega   DATE         NOT NULL,
    hora_entrega   TIME         NOT NULL,
    id_agendamento INT          NOT NULL UNIQUE   
);

CREATE TABLE categoria_produto (
    id_categoria INT AUTO_INCREMENT PRIMARY KEY,
    nome         VARCHAR(50)  NOT NULL,
    descricao    VARCHAR(200)
);

CREATE TABLE produto (
    id_produto     INT AUTO_INCREMENT PRIMARY KEY,
    ncm            CHAR(8)       NOT NULL,
    nome           VARCHAR(100)  NOT NULL,
    descricao      VARCHAR(200),
    codigo_barras  VARCHAR(20)   NOT NULL UNIQUE,
    preco_venda    DECIMAL(10,2) NOT NULL,
    unidade_medida VARCHAR(10)   NOT NULL,
    preco_custo    DECIMAL(10,2) NOT NULL,
    id_categoria   INT           NOT NULL            
);

CREATE TABLE fornecedor (
    id_fornecedor INT AUTO_INCREMENT PRIMARY KEY,
    nome          VARCHAR(100) NOT NULL,
    telefone      VARCHAR(11)  NOT NULL,
    endereco      VARCHAR(200) NOT NULL
);

CREATE TABLE compra (
    id_compra          INT AUTO_INCREMENT PRIMARY KEY,
    data_compra        DATE          NOT NULL,
    numero_nota_fiscal VARCHAR(20),                    
    valor_total        DECIMAL(10,2) NOT NULL,
    status_compra      VARCHAR(20)   NOT NULL DEFAULT 'SOLICITADA',
    id_fornecedor      INT           NOT NULL          
);

CREATE TABLE lote (
    id_lote         INT AUTO_INCREMENT PRIMARY KEY,
    numero_lote     VARCHAR(20)   NOT NULL,
    data_fabricacao DATE          NOT NULL,
    data_validade   DATE          NOT NULL,
    quantidade      DECIMAL(10,3) NOT NULL,             
    custo           DECIMAL(10,2),
    id_produto      INT           NOT NULL,            
    id_compra       INT           NOT NULL             
);

CREATE TABLE venda (
    id_venda    INT AUTO_INCREMENT PRIMARY KEY,
    data        DATE          NOT NULL,
    valor_total DECIMAL(10,2) NOT NULL,
    status      VARCHAR(20)   NOT NULL DEFAULT 'ABERTA',
    id_cliente  INT           NOT NULL                 
);

CREATE TABLE pagamento (
    id_pagamento     INT AUTO_INCREMENT PRIMARY KEY,
    forma_pagamento  VARCHAR(50)   NOT NULL,
    valor_pagamento  DECIMAL(10,2) NOT NULL,
    data_pagamento   DATE          NOT NULL,
    status_pagamento VARCHAR(20)   NOT NULL DEFAULT 'PENDENTE',
    id_venda         INT           NOT NULL             
);

CREATE TABLE item_venda (
    id_venda       INT           NOT NULL,
    id_produto     INT           NOT NULL,
    quantidade     DECIMAL(10,3) NOT NULL DEFAULT 1,
    preco_unitario DECIMAL(10,2) NOT NULL,
    PRIMARY KEY (id_venda, id_produto)
);

CREATE TABLE venda_servico (
    id_venda   INT NOT NULL,
    id_servico INT NOT NULL,
    PRIMARY KEY (id_venda, id_servico)
);

ALTER TABLE pet ADD CONSTRAINT fk_pet_cliente
    FOREIGN KEY (id_cliente) REFERENCES cliente (id_cliente)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE historico ADD CONSTRAINT fk_historico_pet
    FOREIGN KEY (id_pet) REFERENCES pet (id_pet)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE agendamento ADD CONSTRAINT fk_agendamento_pet
    FOREIGN KEY (id_pet) REFERENCES pet (id_pet)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE agendamento ADD CONSTRAINT fk_agendamento_funcionario
    FOREIGN KEY (id_funcionario) REFERENCES funcionario (id_funcionario)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE agendamento_servico ADD CONSTRAINT fk_agsrv_agendamento
    FOREIGN KEY (id_agendamento) REFERENCES agendamento (id_agendamento)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE agendamento_servico ADD CONSTRAINT fk_agsrv_servico
    FOREIGN KEY (id_servico) REFERENCES servico (id_servico)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE funcionario_servico ADD CONSTRAINT fk_funsrv_funcionario
    FOREIGN KEY (id_funcionario) REFERENCES funcionario (id_funcionario)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE funcionario_servico ADD CONSTRAINT fk_funsrv_servico
    FOREIGN KEY (id_servico) REFERENCES servico (id_servico)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE transporte ADD CONSTRAINT fk_transporte_agendamento
    FOREIGN KEY (id_agendamento) REFERENCES agendamento (id_agendamento)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE entrega ADD CONSTRAINT fk_entrega_agendamento
    FOREIGN KEY (id_agendamento) REFERENCES agendamento (id_agendamento)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE produto ADD CONSTRAINT fk_produto_categoria
    FOREIGN KEY (id_categoria) REFERENCES categoria_produto (id_categoria)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE compra ADD CONSTRAINT fk_compra_fornecedor
    FOREIGN KEY (id_fornecedor) REFERENCES fornecedor (id_fornecedor)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE lote ADD CONSTRAINT fk_lote_produto
    FOREIGN KEY (id_produto) REFERENCES produto (id_produto)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE lote ADD CONSTRAINT fk_lote_compra
    FOREIGN KEY (id_compra) REFERENCES compra (id_compra)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE venda ADD CONSTRAINT fk_venda_cliente
    FOREIGN KEY (id_cliente) REFERENCES cliente (id_cliente)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE pagamento ADD CONSTRAINT fk_pagamento_venda
    FOREIGN KEY (id_venda) REFERENCES venda (id_venda)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE item_venda ADD CONSTRAINT fk_itemvenda_venda
    FOREIGN KEY (id_venda) REFERENCES venda (id_venda)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE item_venda ADD CONSTRAINT fk_itemvenda_produto
    FOREIGN KEY (id_produto) REFERENCES produto (id_produto)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE venda_servico ADD CONSTRAINT fk_vendasrv_venda
    FOREIGN KEY (id_venda) REFERENCES venda (id_venda)
    ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE venda_servico ADD CONSTRAINT fk_vendasrv_servico
    FOREIGN KEY (id_servico) REFERENCES servico (id_servico)
    ON UPDATE CASCADE ON DELETE RESTRICT;


ALTER TABLE cliente ADD CONSTRAINT ck_cliente_cpf
    CHECK (cpf REGEXP '^[0-9]{11}$');

ALTER TABLE funcionario ADD CONSTRAINT ck_funcionario_cpf
    CHECK (cpf REGEXP '^[0-9]{11}$');

ALTER TABLE pet ADD CONSTRAINT ck_pet_peso
    CHECK (peso > 0);

ALTER TABLE pet ADD CONSTRAINT ck_pet_sexo
    CHECK (sexo IN ('M', 'F'));

ALTER TABLE servico ADD CONSTRAINT ck_servico_preco
    CHECK (preco >= 0);

ALTER TABLE servico ADD CONSTRAINT ck_servico_tipo
    CHECK (tipo IN ('BANHO', 'TOSA', 'ESTETICA', 'CLINICA'));

ALTER TABLE agendamento ADD CONSTRAINT ck_agendamento_status
    CHECK (status IN ('AGENDADO', 'CONCLUIDO', 'CANCELADO'));

ALTER TABLE transporte ADD CONSTRAINT ck_transporte_status
    CHECK (status IN ('PENDENTE', 'REALIZADO', 'CANCELADO'));

ALTER TABLE transporte ADD CONSTRAINT ck_transporte_tipo
    CHECK (tipo_transporte IN ('BUSCA', 'DEVOLUCAO'));

ALTER TABLE entrega ADD CONSTRAINT ck_entrega_status
    CHECK (status IN ('PENDENTE', 'REALIZADO', 'CANCELADO'));

ALTER TABLE produto ADD CONSTRAINT ck_produto_ncm
    CHECK (ncm REGEXP '^[0-9]{8}$');

ALTER TABLE produto ADD CONSTRAINT ck_produto_preco_venda
    CHECK (preco_venda >= 0);

ALTER TABLE produto ADD CONSTRAINT ck_produto_preco_custo
    CHECK (preco_custo >= 0);

ALTER TABLE compra ADD CONSTRAINT ck_compra_valor_total
    CHECK (valor_total >= 0);

ALTER TABLE compra ADD CONSTRAINT ck_compra_status
    CHECK (status_compra IN ('SOLICITADA', 'RECEBIDA', 'CANCELADA'));

ALTER TABLE lote ADD CONSTRAINT ck_lote_quantidade
    CHECK (quantidade >= 0);

ALTER TABLE lote ADD CONSTRAINT ck_lote_custo
    CHECK (custo >= 0);

ALTER TABLE lote ADD CONSTRAINT ck_lote_datas
    CHECK (data_validade >= data_fabricacao);

ALTER TABLE venda ADD CONSTRAINT ck_venda_valor_total
    CHECK (valor_total >= 0);

ALTER TABLE venda ADD CONSTRAINT ck_venda_status
    CHECK (status IN ('ABERTA', 'FINALIZADA', 'CANCELADA'));

ALTER TABLE pagamento ADD CONSTRAINT ck_pagamento_forma
    CHECK (forma_pagamento IN ('DINHEIRO', 'CARTAO', 'PIX'));

ALTER TABLE pagamento ADD CONSTRAINT ck_pagamento_valor
    CHECK (valor_pagamento > 0);

ALTER TABLE pagamento ADD CONSTRAINT ck_pagamento_status
    CHECK (status_pagamento IN ('PENDENTE', 'CONFIRMADO', 'ESTORNADO'));

ALTER TABLE item_venda ADD CONSTRAINT ck_itemvenda_quantidade
    CHECK (quantidade > 0);

ALTER TABLE item_venda ADD CONSTRAINT ck_itemvenda_preco
    CHECK (preco_unitario >= 0);

