-- 5. SELECT COM JOIN (J01..J08): correspondencias entre tabelas

-- Data de referencia da massa de dados (domingo, ultimo dia da semana-base).
-- Usada no lugar de CURDATE() para o resultado ser o mesmo em qualquer dia de execucao.
SET @hoje = '2026-11-01';

-- J01: Quais pets cada cliente possui?
-- Tabelas: cliente (1,n) pet. Lista os 20 primeiros, em ordem de tutor e de pet.
SELECT c.id_cliente, c.nome AS tutor, p.id_pet, p.nome AS pet, p.especie, p.raca
FROM cliente c
JOIN pet p ON p.id_cliente = c.id_cliente
ORDER BY c.nome, p.nome
LIMIT 20;

-- J02: Qual a agenda do dia (pet, tutor, servicos e funcionario responsavel)?
-- Tabelas: agendamento, pet, cliente, agendamento_servico, servico, funcionario.
-- Os servicos do mesmo agendamento saem na mesma linha (GROUP_CONCAT). Usa @hoje.
SELECT a.id_agendamento, a.data, a.hora, a.status,
       p.nome AS pet, c.nome AS tutor,
       GROUP_CONCAT(s.nome ORDER BY s.nome SEPARATOR ' + ') AS servicos,
       f.nome AS funcionario
FROM agendamento a
JOIN pet p                 ON p.id_pet = a.id_pet
JOIN cliente c             ON c.id_cliente = p.id_cliente
JOIN agendamento_servico x ON x.id_agendamento = a.id_agendamento
JOIN servico s             ON s.id_servico = x.id_servico
JOIN funcionario f         ON f.id_funcionario = a.id_funcionario
WHERE a.data = @hoje
GROUP BY a.id_agendamento, a.data, a.hora, a.status, p.nome, c.nome, f.nome
ORDER BY a.hora;

-- J03: Quais produtos tem a venda 1, com quantidade e subtotal?
-- Tabelas: venda, item_venda, produto. Subtotal = quantidade x preco unitario gravado na venda.
SELECT v.id_venda, v.data, pr.nome AS produto, iv.quantidade, iv.preco_unitario,
       ROUND(iv.quantidade * iv.preco_unitario, 2) AS subtotal
FROM venda v
JOIN item_venda iv ON iv.id_venda = v.id_venda
JOIN produto pr    ON pr.id_produto = iv.id_produto
WHERE v.id_venda = 1
ORDER BY pr.nome;

-- J04: Quais lotes do produto 1 estao disponiveis, na ordem FEFO, com compra e fornecedor?
-- Tabelas: lote, produto, compra, fornecedor.
-- Atende: RN09 (sai primeiro o lote de menor validade). So entram lotes com saldo e dentro da validade (@hoje).
SELECT pr.nome AS produto, l.numero_lote, l.data_validade, l.quantidade,
       f.nome AS fornecedor, c.numero_nota_fiscal
FROM lote l
JOIN produto pr    ON pr.id_produto = l.id_produto
JOIN compra c      ON c.id_compra = l.id_compra
JOIN fornecedor f  ON f.id_fornecedor = c.id_fornecedor
WHERE pr.id_produto = 1 AND l.quantidade > 0 AND l.data_validade >= @hoje
ORDER BY l.data_validade;

-- J05: Quais servicos cada funcionario executa?
-- Tabelas: funcionario, funcionario_servico (associativa N:N), servico.
SELECT f.nome AS funcionario, f.cargo, s.nome AS servico, s.tipo
FROM funcionario f
JOIN funcionario_servico fs ON fs.id_funcionario = f.id_funcionario
JOIN servico s              ON s.id_servico = fs.id_servico
ORDER BY f.nome, s.nome;

-- J06: Como cada venda foi paga (uma venda pode ter varios pagamentos)?
-- Tabelas: venda, pagamento. Lista os 30 primeiros pagamentos.
SELECT v.id_venda, v.data, v.valor_total, pg.forma_pagamento, pg.valor_pagamento, pg.status_pagamento
FROM venda v
JOIN pagamento pg ON pg.id_venda = v.id_venda
ORDER BY v.id_venda, pg.id_pagamento
LIMIT 30;

-- J07: Quais agendamentos tem transporte (busca) e entrega (devolucao)?
-- Tabelas: agendamento, pet, transporte, entrega.
-- Usa LEFT JOIN porque nem todo agendamento tem transporte ou entrega; o WHERE deixa so os que tem ao menos um dos dois.
SELECT a.id_agendamento, a.data, p.nome AS pet,
       t.status AS status_busca, e.status AS status_devolucao
FROM agendamento a
JOIN pet p            ON p.id_pet = a.id_pet
LEFT JOIN transporte t ON t.id_agendamento = a.id_agendamento
LEFT JOIN entrega e    ON e.id_agendamento = a.id_agendamento
WHERE t.id_transporte IS NOT NULL OR e.id_entrega IS NOT NULL
ORDER BY a.data, a.hora;

-- J08: Quais clientes cadastrados nunca fizeram uma compra?
-- Tabelas: cliente, venda. O LEFT JOIN com o filtro "venda IS NULL" deixa so os clientes sem nenhuma venda.
SELECT c.id_cliente, c.nome
FROM cliente c
LEFT JOIN venda v ON v.id_cliente = c.id_cliente
WHERE v.id_venda IS NULL
ORDER BY c.nome;

-- 6. UPDATE (U01..U08): alterando dados que ja existem
/* os ids usados aqui existem na massa de dados */

-- U01: Registrar a chegada da compra 13 (status e numero da nota fiscal).
-- Atende: RN14 (toda compra recebida tem nota fiscal). So altera se a compra ainda estiver SOLICITADA.
UPDATE compra
SET status_compra = 'RECEBIDA', numero_nota_fiscal = '000004711'
WHERE id_compra = 13 AND status_compra = 'SOLICITADA';

-- U02 (INSERT): Registrar o lote recebido na compra 13 (toda compra recebida tem ao menos um lote).
-- Atende: RN14. So insere se a compra 13 ja estiver RECEBIDA e o produto 1 existir.
INSERT INTO lote (numero_lote, data_fabricacao, data_validade, quantidade, custo, id_produto, id_compra)
SELECT 'L13-001', '2026-09-15', '2027-09-15', 40, 8.50, 1, 13
FROM compra c
WHERE c.id_compra = 13 AND c.status_compra = 'RECEBIDA'
  AND EXISTS (SELECT 1 FROM produto p WHERE p.id_produto = 1);

-- U03: Baixa de estoque: venda de 2 unidades tiradas do lote de menor validade.
-- Atende: RF05 e RN09 (FEFO). A condicao quantidade >= 2 evita saldo negativo e lote vencido nao e usado.
UPDATE lote
SET quantidade = quantidade - 2
WHERE id_lote = 1 AND quantidade >= 2 AND data_validade >= @hoje;

-- U04: Cancelar o agendamento 1, sem apagar nada.
-- Atende: RN12 (cancelar atualiza tambem o transporte e a entrega ligados a ele: U05 e U06).
UPDATE agendamento SET status = 'CANCELADO' WHERE id_agendamento = 1 AND status = 'AGENDADO';

-- U05: Cancelar o transporte (busca) do agendamento 1, se ainda estiver pendente.
UPDATE transporte  SET status = 'CANCELADO' WHERE id_agendamento = 1 AND status = 'PENDENTE';

-- U06: Cancelar a entrega (devolucao) do agendamento 1, se ainda estiver pendente.
UPDATE entrega     SET status = 'CANCELADO' WHERE id_agendamento = 1 AND status = 'PENDENTE';

-- U07: Reajuste de 5% no preco de venda de todos os produtos da categoria 1 (arredondado em 2 casas).
UPDATE produto
SET preco_venda = ROUND(preco_venda * 1.05, 2)
WHERE id_categoria = 1;

-- U08: Confirmar os pagamentos em PIX que estavam pendentes.
-- Atende: RN13 (so os pagamentos confirmados contam para finalizar a venda).
UPDATE pagamento
SET status_pagamento = 'CONFIRMADO'
WHERE forma_pagamento = 'PIX' AND status_pagamento = 'PENDENTE';

-- 7. DELETE (D01..D04): apagando linhas
/* sempre o filho antes do pai: as FKs usam ON DELETE RESTRICT */

-- D01: Remover o vinculo do funcionario 1 com o servico 1.
-- Apaga so a linha da tabela associativa funcionario_servico; o funcionario e o servico continuam cadastrados.
DELETE FROM funcionario_servico WHERE id_funcionario = 1 AND id_servico = 1;

-- D02: Apagar o pet do cadastro duplicado (cliente 999), que nunca teve historico nem agendamento.
-- Vem antes do D03 porque o pet e filho do cliente (ON DELETE RESTRICT).
DELETE FROM pet
WHERE id_cliente = 999
  AND NOT EXISTS (SELECT 1 FROM historico h WHERE h.id_pet = pet.id_pet)
  AND NOT EXISTS (SELECT 1 FROM agendamento a WHERE a.id_pet = pet.id_pet);

-- D03: Apagar o cadastro duplicado (cliente 999), so se ele nao tiver mais pet nem venda.
DELETE FROM cliente
WHERE id_cliente = 999
  AND NOT EXISTS (SELECT 1 FROM pet p WHERE p.id_cliente = cliente.id_cliente)
  AND NOT EXISTS (SELECT 1 FROM venda v WHERE v.id_cliente = cliente.id_cliente);

-- D04 (exemplo, nao executar): apagar um cliente que tem pet ou venda e bloqueado pelo banco (ERRO 1451).
-- DELETE FROM cliente WHERE id_cliente = 1;

-- 8. CONSULTAS GERENCIAIS (G01..G11)

-- G01: Quanto resta em estoque (lotes dentro da validade) de cada produto vendido na ultima semana e para quantos dias isso dura?
-- Atende: P1 (vendas e estoque nao integrados) e KPI cobertura de estoque em dias
SELECT pr.id_produto, pr.nome AS produto, pr.unidade_medida,
       COALESCE(est.saldo_valido, 0) AS saldo_em_lotes_validos,
       vend.qtd_7d AS vendido_7_dias,
       ROUND(COALESCE(est.saldo_valido, 0) / (vend.qtd_7d / 7), 1) AS cobertura_dias
FROM produto pr
JOIN (SELECT iv.id_produto, SUM(iv.quantidade) AS qtd_7d
      FROM item_venda iv
      JOIN venda v ON v.id_venda = iv.id_venda
      WHERE v.status = 'FINALIZADA'
        AND v.data BETWEEN DATE_SUB(@hoje, INTERVAL 6 DAY) AND @hoje
      GROUP BY iv.id_produto) vend ON vend.id_produto = pr.id_produto
LEFT JOIN (SELECT id_produto, SUM(quantidade) AS saldo_valido
           FROM lote
           WHERE data_validade >= @hoje
           GROUP BY id_produto) est ON est.id_produto = pr.id_produto
ORDER BY cobertura_dias ASC
LIMIT 10;

-- G02: Quais lotes vencem nos proximos 30 dias e quanto dinheiro (a custo) esta parado neles?
-- Atende: P1 (estoque desatualizado) e KPI valor em risco por validade
SELECT pr.nome AS produto, l.numero_lote, l.data_validade,
       DATEDIFF(l.data_validade, @hoje) AS dias_para_vencer,
       l.quantidade,
       ROUND(l.quantidade * COALESCE(l.custo, pr.preco_custo), 2) AS valor_em_risco
FROM lote l
JOIN produto pr ON pr.id_produto = l.id_produto
WHERE l.quantidade > 0
  AND l.data_validade BETWEEN @hoje AND DATE_ADD(@hoje, INTERVAL 30 DAY)
ORDER BY l.data_validade, valor_em_risco DESC;

-- G03: Qual a margem media de cada categoria e quantos produtos estao com margem abaixo de 20%?
-- Atende: P2 (cadastro manual de preco de custo) e KPI margem bruta por categoria
SELECT cp.nome AS categoria, COUNT(*) AS qtd_produtos,
       ROUND(AVG(pr.preco_venda - pr.preco_custo), 2) AS margem_media_reais,
       ROUND(AVG((pr.preco_venda - pr.preco_custo) / NULLIF(pr.preco_venda, 0)) * 100, 1) AS margem_media_pct,
       SUM((pr.preco_venda - pr.preco_custo) / NULLIF(pr.preco_venda, 0) < 0.20) AS produtos_margem_abaixo_20pct
FROM produto pr
JOIN categoria_produto cp ON cp.id_categoria = pr.id_categoria
GROUP BY cp.id_categoria, cp.nome
ORDER BY margem_media_pct;

-- G04: Qual o historico completo de um pet, juntando prontuario clinico e atendimentos do pet shop?
-- Atende: P3 (pet shop e clinica sem integracao)
SELECT p.nome AS pet, x.data, x.origem, x.tipo, x.detalhe
FROM pet p
JOIN (SELECT h.id_pet, h.data, 'CLINICA' AS origem, h.tipo_atendimento AS tipo, h.descricao AS detalhe
      FROM historico h
      UNION ALL
      SELECT a.id_pet, a.data, 'PETSHOP',
             GROUP_CONCAT(s.nome ORDER BY s.nome SEPARATOR ' + '),
             CONCAT('Agendamento ', a.status)
      FROM agendamento a
      JOIN agendamento_servico ags ON ags.id_agendamento = a.id_agendamento
      JOIN servico s               ON s.id_servico = ags.id_servico
      GROUP BY a.id_agendamento, a.id_pet, a.data, a.status) x ON x.id_pet = p.id_pet
WHERE p.id_pet = 1
ORDER BY x.data DESC;

-- G05: Quais clientes usaram a clinica e o banho e tosa nos ultimos 30 dias?
-- Atende: P3 (clientes e atendimentos compartilhados) e KPI clientes nas duas frentes
SELECT c.id_cliente, c.nome AS tutor,
       COUNT(DISTINCT CASE WHEN s.tipo = 'CLINICA' THEN a.id_agendamento END)  AS atendimentos_clinica,
       COUNT(DISTINCT CASE WHEN s.tipo <> 'CLINICA' THEN a.id_agendamento END) AS atendimentos_banho_tosa
FROM cliente c
JOIN pet p                   ON p.id_cliente = c.id_cliente
JOIN agendamento a           ON a.id_pet = p.id_pet AND a.status = 'CONCLUIDO'
JOIN agendamento_servico ags ON ags.id_agendamento = a.id_agendamento
JOIN servico s               ON s.id_servico = ags.id_servico
WHERE a.data BETWEEN DATE_SUB(@hoje, INTERVAL 30 DAY) AND @hoje
GROUP BY c.id_cliente, c.nome
HAVING atendimentos_clinica > 0 AND atendimentos_banho_tosa > 0
ORDER BY c.nome;

-- G06: Quanto foi comprado de cada fornecedor, quantas compras estao abertas e quantas foram recebidas sem nota?
-- Atende: P4 (fornecedores sem cadastro estruturado) e KPI valor comprado por fornecedor
SELECT f.id_fornecedor, f.nome AS fornecedor,
       COUNT(c.id_compra) AS qtd_compras,
       ROUND(COALESCE(SUM(c.valor_total), 0), 2) AS valor_comprado,
       COALESCE(SUM(c.status_compra = 'SOLICITADA'), 0) AS em_aberto,
       COALESCE(SUM(c.status_compra = 'RECEBIDA' AND c.numero_nota_fiscal IS NULL), 0) AS recebidas_sem_nf,
       (SELECT COUNT(*) FROM lote l JOIN compra c2 ON c2.id_compra = l.id_compra
        WHERE c2.id_fornecedor = f.id_fornecedor) AS lotes_recebidos
FROM fornecedor f
LEFT JOIN compra c ON c.id_fornecedor = f.id_fornecedor
GROUP BY f.id_fornecedor, f.nome
ORDER BY valor_comprado DESC;

-- G07: Quais pedidos de compra ainda nao foram recebidos e ha quantos dias estao em aberto?
-- Atende: P4 (compras sem rastreio)
SELECT c.id_compra, f.nome AS fornecedor, c.data_compra,
       DATEDIFF(@hoje, c.data_compra) AS dias_em_aberto, c.valor_total
FROM compra c
JOIN fornecedor f ON f.id_fornecedor = c.id_fornecedor
WHERE c.status_compra = 'SOLICITADA'
ORDER BY dias_em_aberto DESC;

-- G08: Quanto entrou no caixa em cada dia da ultima semana, por forma de pagamento?
-- Atende: KPI recebimento por forma de pagamento e dia (fechamento de caixa)
SELECT pg.data_pagamento AS dia, pg.forma_pagamento,
       COUNT(*) AS qtd_pagamentos, ROUND(SUM(pg.valor_pagamento), 2) AS total_recebido
FROM pagamento pg
WHERE pg.status_pagamento = 'CONFIRMADO'
  AND pg.data_pagamento BETWEEN DATE_SUB(@hoje, INTERVAL 6 DAY) AND @hoje
GROUP BY pg.data_pagamento, pg.forma_pagamento
ORDER BY dia, pg.forma_pagamento;

-- G09: Qual o faturamento e o ticket medio por dia (vendas finalizadas)?
-- Atende: KPI faturamento diario e ticket medio
SELECT v.data, COUNT(*) AS qtd_vendas,
       ROUND(SUM(v.valor_total), 2) AS faturamento,
       ROUND(AVG(v.valor_total), 2) AS ticket_medio
FROM venda v
WHERE v.status = 'FINALIZADA'
  AND v.data BETWEEN DATE_SUB(@hoje, INTERVAL 6 DAY) AND @hoje
GROUP BY v.data
ORDER BY v.data;

-- G10: Quais servicos mais faturam e quantas vezes foram vendidos?
-- Atende: KPI faturamento por servico
SELECT s.tipo, s.nome AS servico, COUNT(*) AS qtd_vendida, ROUND(SUM(s.preco), 2) AS faturamento
FROM venda_servico vs
JOIN venda v   ON v.id_venda = vs.id_venda AND v.status = 'FINALIZADA'
JOIN servico s ON s.id_servico = vs.id_servico
GROUP BY s.id_servico, s.tipo, s.nome
ORDER BY faturamento DESC;

-- G11: Quantos atendimentos cada funcionario concluiu e qual a taxa de cancelamento nos ultimos 7 dias?
-- Atende: KPI taxa de cancelamento e atendimentos por funcionario
SELECT f.nome AS funcionario, f.cargo,
       COUNT(a.id_agendamento) AS agendamentos,
       COALESCE(SUM(a.status = 'CONCLUIDO'), 0) AS concluidos,
       COALESCE(SUM(a.status = 'CANCELADO'), 0) AS cancelados,
       ROUND(100 * SUM(a.status = 'CANCELADO') / NULLIF(COUNT(a.id_agendamento), 0), 1) AS pct_cancelamento
FROM funcionario f
LEFT JOIN agendamento a ON a.id_funcionario = f.id_funcionario
                       AND a.data BETWEEN DATE_SUB(@hoje, INTERVAL 6 DAY) AND @hoje
GROUP BY f.id_funcionario, f.nome, f.cargo
ORDER BY concluidos DESC;

-- 9. CONSULTAS DE AUDITORIA (A01..A07)

-- A01: Existe venda finalizada cujo total de pagamentos confirmados e diferente do valor da venda?
-- Verifica: RN13 (a venda so finaliza com pagamentos confirmados iguais ao valor)
SELECT v.id_venda, v.data, v.valor_total,
       COALESCE(SUM(CASE WHEN pg.status_pagamento = 'CONFIRMADO' THEN pg.valor_pagamento END), 0) AS total_confirmado
FROM venda v
LEFT JOIN pagamento pg ON pg.id_venda = v.id_venda
WHERE v.status = 'FINALIZADA'
GROUP BY v.id_venda, v.data, v.valor_total
HAVING total_confirmado <> v.valor_total;

-- A02: Existe compra recebida sem numero de nota fiscal?
-- Verifica: RN14 (toda compra recebida tem nota fiscal registrada)
SELECT c.id_compra, f.nome AS fornecedor, c.data_compra, c.status_compra
FROM compra c
JOIN fornecedor f ON f.id_fornecedor = c.id_fornecedor
WHERE c.status_compra = 'RECEBIDA' AND c.numero_nota_fiscal IS NULL;

-- A03: Existe compra recebida sem nenhum lote registrado?
-- Verifica: RN14 (itens conferidos viram lotes) e DER Compra 1,1 - Registra - 1,n Lote
SELECT c.id_compra, f.nome AS fornecedor, c.data_compra, c.numero_nota_fiscal
FROM compra c
JOIN fornecedor f ON f.id_fornecedor = c.id_fornecedor
LEFT JOIN lote l  ON l.id_compra = c.id_compra
WHERE c.status_compra = 'RECEBIDA' AND l.id_lote IS NULL;

-- A04: Existe horario com mais agendamentos de banho e tosa do que funcionarios operacionais?
-- Verifica: RN08 (capacidade operacional por horario)
SELECT a.data, a.hora, COUNT(*) AS agendamentos_ativos, cap.total AS funcionarios_operacionais
FROM agendamento a
JOIN funcionario f ON f.id_funcionario = a.id_funcionario AND f.cargo = 'Banho e Tosa'
CROSS JOIN (SELECT COUNT(*) AS total FROM funcionario WHERE cargo = 'Banho e Tosa') cap
WHERE a.status <> 'CANCELADO'
GROUP BY a.data, a.hora, cap.total
HAVING COUNT(*) > cap.total
ORDER BY a.data, a.hora;

-- A05: Existe lote vencido que ainda tem saldo em estoque?
-- Verifica: RN05 (produto de lote vencido nao pode ser vendido)
SELECT pr.nome AS produto, l.numero_lote, l.data_validade, l.quantidade
FROM lote l
JOIN produto pr ON pr.id_produto = l.id_produto
WHERE l.data_validade < @hoje AND l.quantidade > 0
ORDER BY l.data_validade;

-- A06: Existe agendamento cancelado com transporte ou entrega ainda pendente?
-- Verifica: RN12 (cancelar atualiza tambem o transporte vinculado)
SELECT a.id_agendamento, a.data, p.nome AS pet,
       t.status AS status_transporte, e.status AS status_entrega
FROM agendamento a
JOIN pet p             ON p.id_pet = a.id_pet
LEFT JOIN transporte t ON t.id_agendamento = a.id_agendamento
LEFT JOIN entrega e    ON e.id_agendamento = a.id_agendamento
WHERE a.status = 'CANCELADO'
  AND (t.status = 'PENDENTE' OR e.status = 'PENDENTE');

-- A07: Existe pagamento com data anterior a data da venda?
-- Verifica: RN13 (todo pagamento tem data coerente com a venda)
SELECT pg.id_pagamento, pg.id_venda, v.data AS data_venda, pg.data_pagamento
FROM pagamento pg
JOIN venda v ON v.id_venda = pg.id_venda
WHERE pg.data_pagamento < v.data;
